pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public {
        // Restrict to admissible inputs: feeRate > 5000 to potentially trigger the bug
        vm.assume(_feeRate > 5000);

        // Call initialize and catch any revert
        bool ok;
        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference always reverts for feeRate > 5000; the mutant may succeed,
        // or if it succeeds, the stored feeRate must not exceed 5000.
        if (ok) {
            assertTrue(c.feeRate() <= 5000, "feeRate stored > 5000 after successful initialize");
        }
        // If it reverted, no assertion needed — the reference behavior is a revert,
        // which is safe. The test will fail only when the mutant does NOT revert
        // AND stores a feeRate > 5000.
    }
}

